content:
:root {
  --bg-space: #030712;
  --bg-overlay: rgba(15, 23, 42, 0.75);
  --bg-overlay-hover: rgba(30, 41, 59, 0.85);
  --bg-card: rgba(17, 24, 39, 0.8);
  --bg-stat: rgba(31, 41, 55, 0.6);
  --border-subtle: rgba(255, 255, 255, 0.12);
  --border-active: rgba(56, 189, 248, 0.6);
  --text-primary: #f9fafb;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;
  --accent-cyan: #38bdf8;
  --accent-cyan-glow: rgba(56, 189, 248, 0.35);
  --accent-gold: #fbbf24;
  --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --shadow-panel: 0 16px 36px rgba(0, 0, 0, 0.6), 0 0 1px 1px rgba(255, 255, 255, 0.1);
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-space);
  color: var(--text-primary);
  font-family: var(--font-main);
  user-select: none;
  -webkit-user-select: none;
}

#root {
  width: 100%;
  height: 100%;
}

/* メインコンテナ */
.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background-color: var(--bg-space);
}

/* 3Dキャンバス領域 */
.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  outline: none;
}

.canvas-container canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
}

/* ローディングオーバーレイ */
.loading-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 50;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  background: radial-gradient(circle at center, #0b1329 0%, #030712 100%);
  color: var(--text-primary);
  font-size: 1.125rem;
  letter-spacing: 0.05em;
}

.loading-overlay::after {
  content: "";
  width: 44px;
  height: 44px;
  border: 3px solid rgba(56, 189, 248, 0.2);
  border-top-color: var(--accent-cyan);
  border-radius: 50%;
  animation: spin 0.9s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* ヘッダーバナー */
.header-banner {
  position: absolute;
  top: 16px;
  left: 20px;
  z-index: 10;
  pointer-events: auto;
  background: var(--bg-overlay);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 12px 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.header-title {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: #ffffff;
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-title::before {
  content: "";
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 10px var(--accent-cyan);
}

.header-subtitle {
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-top: 3px;
}

/* 操作ヒント */
.legend-hint {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 10;
  pointer-events: none;
  background: var(--bg-overlay);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 8px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  font-size: 0.75rem;
  color: var(--text-secondary);
  line-height: 1.5;
  text-align: right;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

/* コントロール全体ルート */
.controls-root {
  position: absolute;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 20;
  width: calc(100% - 32px);
  max-width: 960px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: auto;
}

/* 操作バー (速度、一時停止、軌道線) */
.control-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--bg-overlay);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  padding: 10px 18px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-panel);
  flex-wrap: wrap;
}

/* ボタン共通 */
.btn-control {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 14px;
  min-height: 38px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.btn-control:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.25);
  transform: translateY(-1px);
}

.btn-control:active {
  transform: translateY(0);
}

/* アクティブボタン */
.btn-active {
  background: rgba(56, 189, 248, 0.18);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
  box-shadow: 0 0 12px var(--accent-cyan-glow);
}

/* 速度スライダーグループ */
.speed-slider-group {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 200px;
}

.slider-label {
  font-size: 0.8rem;
  color: var(--text-secondary);
  font-weight: 500;
  white-space: nowrap;
}

.speed-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.15);
  outline: none;
  cursor: pointer;
  transition: background 0.2s;
}

.speed-slider:hover {
  background: rgba(255, 255, 255, 0.25);
}

.speed-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 10px var(--accent-cyan);
  cursor: pointer;
  border: 2px solid #ffffff;
  transition: transform 0.15s ease;
}

.speed-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
}

.speed-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 10px var(--accent-cyan);
  cursor: pointer;
  border: 2px solid #ffffff;
}

/* 惑星クイック選択バー */
.planet-quick-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  padding: 6px 10px;
  background: var(--bg-overlay);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-panel);
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.planet-quick-bar::-webkit-scrollbar {
  display: none;
}

/* 惑星クイックボタン */
.planet-quick-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  min-height: 34px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
  transition: all 0.2s ease;
}

.planet-quick-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.25);
  transform: translateY(-1px);
}

.planet-quick-btn-active {
  background: rgba(56, 189, 248, 0.2);
  border-color: var(--accent-cyan);
  color: #ffffff;
  box-shadow: 0 0 12px var(--accent-cyan-glow);
}

/* 惑星詳細情報パネル */
.info-panel {
  position: absolute;
  top: 16px;
  right: 20px;
  z-index: 30;
  width: 340px;
  max-height: calc(100vh - 120px);
  overflow-y: auto;
  background: var(--bg-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-panel);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  animation: slideInRight 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}

@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.info-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 12px;
}

.info-title {
  font-size: 1.4rem;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.2;
}

.info-subtitle {
  font-size: 0.85rem;
  color: var(--accent-cyan);
  font-weight: 500;
  margin-top: 2px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.info-close-btn {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-subtle);
  border-radius: 50%;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 1.1rem;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.info-close-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  color: #ffffff;
  transform: rotate(90deg);
}

.info-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.info-stat-box {
  background: var(--bg-stat);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.info-stat-label {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.info-stat-value {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-primary);
  word-break: break-all;
}

.info-description {
  font-size: 0.85rem;
  line-height: 1.6;
  color: var(--text-secondary);
  background: rgba(0, 0, 0, 0.2);
  border-radius: var(--radius-md);
  padding: 12px;
  border-left: 3px solid var(--accent-cyan);
}

/* スマホ・タブレット向けレスポンシブ対応 */
@media (max-width: 768px) {
  .header-banner {
    top: 10px;
    left: 10px;
    right: 10px;
    padding: 10px 14px;
  }

  .header-title {
    font-size: 1.05rem;
  }

  .header-subtitle {
    font-size: 0.72rem;
  }

  .legend-hint {
    display: none;
  }

  .controls-root {
    bottom: 10px;
    width: calc(100% - 20px);
    gap: 8px;
  }

  .control-bar {
    padding: 8px 12px;
    gap: 8px;
  }

  .speed-slider-group {
    order: 3;
    width: 100%;
    min-width: 100%;
  }

  .btn-control {
    padding: 6px 10px;
    font-size: 0.78rem;
    min-height: 34px;
  }

  .info-panel {
    top: auto;
    bottom: 80px;
    left: 10px;
    right: 10px;
    width: auto;
    max-height: 55vh;
    padding: 16px;
    animation: slideInUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes slideInUp {
    from {
      opacity: 0;
      transform: translateY(20px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

export interface MoonData {
  name: string;
  radius: number;
  distance: number;
  speed: number;
  color: string;
}

export interface RingData {
  innerRadius: number;
  outerRadius: number;
  color: string;
}

export interface PlanetData {
  id: string;
  name: string;
  enName: string;
  radius: number;
  distance: number;
  orbitSpeed: number;
  rotationSpeed: number;
  color: string;
  ring?: RingData;
  moons?: MoonData[];
  description: string;
  diameterKm: string;
  distanceKm: string;
  periodDays: string;
  temperature: string;
}

export interface SimulationState {
  speed: number;
  isPaused: boolean;
  showOrbits: boolean;
  selectedPlanetId: string | null;
}

export interface SolarControlsProps {
  planets: PlanetData[];
  simulationState: SimulationState;
  onSpeedChange: (speed: number) => void;
  onTogglePause: () => void;
  onToggleOrbits: () => void;
  onSelectPlanet: (id: string | null) => void;
}

export interface SolarSystemViewProps {
  planets: PlanetData[];
  simulationState: SimulationState;
  onSelectPlanet: (id: string | null) => void;
}

import { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { PlanetData, SolarSystemViewProps } from '../types';

interface PlanetMeshEntry {
  id: string;
  data: PlanetData;
  pivot: THREE.Group;
  mesh: THREE.Mesh;
  moons: Array<{ mesh: THREE.Mesh; pivot: THREE.Group; speed: number }>;
  orbitRadius: number;
  orbitLine?: THREE.Line;
}

export default function SolarSystemView({
  planets = [],
  simulationState,
  onSelectPlanet
}: SolarSystemViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Three.js インスタンス保持
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const controlsRef = useRef<OrbitControls | null>(null);
  const planetEntriesRef = useRef<PlanetMeshEntry[]>([]);
  const animFrameIdRef = useRef<number | null>(null);

  // アニメーション・ターゲット補間用
  const targetCamPosRef = useRef<THREE.Vector3 | null>(null);
  const targetLookAtRef = useRef<THREE.Vector3 | null>(null);
  const simulationStateRef = useRef(simulationState);

  // simulationStateの変更をrefに反映
  useEffect(() => {
    simulationStateRef.current = simulationState;
  }, [simulationState]);

  // 軌道線表示切り替えの反映
  useEffect(() => {
    planetEntriesRef.current.forEach((entry) => {
      if (entry.orbitLine) {
        entry.orbitLine.visible = simulationState.showOrbits;
      }
    });
  }, [simulationState.showOrbits]);

  // 選択惑星が変化したときのカメラ追従ターゲット設定
  useEffect(() => {
    if (!simulationState.selectedPlanetId) {
      // 太陽系全体俯瞰視点へ復旧
      targetCamPosRef.current = new THREE.Vector3(0, 110, 170);
      targetLookAtRef.current = new THREE.Vector3(0, 0, 0);
      return;
    }

    const selected = planetEntriesRef.current.find(
      (p) => p.id === simulationState.selectedPlanetId
    );

    if (selected) {
      const worldPos = new THREE.Vector3();
      selected.mesh.getWorldPosition(worldPos);

      const offsetDist = Math.max(selected.data.radius * 3.5, 9);
      targetCamPosRef.current = new THREE.Vector3(
        worldPos.x + offsetDist * 0.8,
        worldPos.y + offsetDist * 0.6,
        worldPos.z + offsetDist
      );
      targetLookAtRef.current = worldPos.clone();
    }
  }, [simulationState.selectedPlanetId]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // 1. シーン構築
    const scene = new THREE.Scene();
    sceneRef.current = scene;
    scene.fog = new THREE.FogExp2(0x030712, 0.0012);

    // 2. カメラ設定
    const width = container.clientWidth || window.innerWidth;
    const height = container.clientHeight || window.innerHeight;
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 2000);
    camera.position.set(0, 110, 170);
    cameraRef.current = camera;

    // 3. レンダラー構築
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    container.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // 4. OrbitControls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.minDistance = 8;
    controls.maxDistance = 600;
    controls.maxPolarAngle = Math.PI / 2 + 0.1;
    controlsRef.current = controls;

    // 5. 環境ライト & 太陽ポイントライト
    const ambientLight = new THREE.AmbientLight(0x222938, 0.6);
    scene.add(ambientLight);

    const sunLight = new THREE.PointLight(0xfff7e6, 2.5, 800, 0.5);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);

    // 6. 星空背景（パーティクル生成）
    const starCount = 3500;
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = new Float32Array(starCount * 3);
    const starColors = new Float32Array(starCount * 3);

    for (let i = 0; i < starCount * 3; i += 3) {
      const radius = 600 + Math.random() * 500;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(Math.random() * 2 - 1);

      starPositions[i] = radius * Math.sin(phi) * Math.cos(theta);
      starPositions[i + 1] = radius * Math.sin(phi) * Math.sin(theta);
      starPositions[i + 2] = radius * Math.cos(phi);

      const starShade = 0.7 + Math.random() * 0.3;
      starColors[i] = starShade;
      starColors[i + 1] = starShade * 0.95;
      starColors[i + 2] = starShade * (0.8 + Math.random() * 0.2);
    }

    starGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
    starGeometry.setAttribute('color', new THREE.BufferAttribute(starColors, 3));
    const starMaterial = new THREE.PointsMaterial({
      size: 1.5,
      vertexColors: true,
      transparent: true,
      opacity: 0.85
    });
    const starField = new THREE.Points(starGeometry, starMaterial);
    scene.add(starField);

    // 7. 各惑星・太陽メッシュ生成
    const entries: PlanetMeshEntry[] = [];
    const sphereGeo = new THREE.SphereGeometry(1, 48, 48);

    planets.forEach((p) => {
      const pivot = new THREE.Group();
      scene.add(pivot);

      let mat: THREE.Material;
      if (p.id === 'sun') {
        // 発光マテリアル（太陽）
        mat = new THREE.MeshBasicMaterial({
          color: new THREE.Color(p.color)
        });
      } else {
        // 標準マテリアル（惑星）
        mat = new THREE.MeshStandardMaterial({
          color: new THREE.Color(p.color),
          roughness: 0.65,
          metalness: 0.1
        });
      }

      const mesh = new THREE.Mesh(sphereGeo, mat);
      mesh.scale.set(p.radius, p.radius, p.radius);
      mesh.position.set(p.distance, 0, 0);
      mesh.userData = { id: p.id };
      pivot.add(mesh);

      // 太陽のグロー表現（外殻）
      if (p.id === 'sun') {
        const glowGeo = new THREE.SphereGeometry(p.radius * 1.15, 32, 32);
        const glowMat = new THREE.MeshBasicMaterial({
          color: 0xff8800,
          transparent: true,
          opacity: 0.2,
          side: THREE.BackSide
        });
        const glowMesh = new THREE.Mesh(glowGeo, glowMat);
        mesh.add(glowMesh);
      }

      // 土星・天王星等の環
      if (p.ring) {
        const ringGeo = new THREE.RingGeometry(p.ring.innerRadius, p.ring.outerRadius, 64);
        const ringMat = new THREE.MeshStandardMaterial({
          color: new THREE.Color(p.color),
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.7
        });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.rotation.x = Math.PI / 2.3;
        mesh.add(ringMesh);
      }

      // 衛星（地球の月など）
      const moonsList: Array<{ mesh: THREE.Mesh; pivot: THREE.Group; speed: number }> = [];
      if (p.moons && p.moons.length > 0) {
        p.moons.forEach((m) => {
          const moonPivot = new THREE.Group();
          mesh.add(moonPivot);

          const moonMat = new THREE.MeshStandardMaterial({
            color: new THREE.Color(m.color),
            roughness: 0.8
          });
          const moonMesh = new THREE.Mesh(sphereGeo, moonMat);
          moonMesh.scale.set(m.radius, m.radius, m.radius);
          moonMesh.position.set(m.distance, 0, 0);
          moonPivot.add(moonMesh);

          moonsList.push({
            mesh: moonMesh,
            pivot: moonPivot,
            speed: m.speed
          });
        });
      }

      // 軌道ライン描画（円弧）
      let orbitLine: THREE.Line | undefined;
      if (p.distance > 0) {
        const segments = 128;
        const lineGeo = new THREE.BufferGeometry();
        const linePoints: number[] = [];

        for (let i = 0; i <= segments; i++) {
          const theta = (i / segments) * Math.PI * 2;
          linePoints.push(Math.cos(theta) * p.distance, 0, Math.sin(theta) * p.distance);
        }

        lineGeo.setAttribute('position', new THREE.Float32BufferAttribute(linePoints, 3));
        const lineMat = new THREE.LineBasicMaterial({
          color: 0x38bdf8,
          transparent: true,
          opacity: 0.25
        });
        orbitLine = new THREE.Line(lineGeo, lineMat);
        orbitLine.visible = simulationStateRef.current.showOrbits;
        scene.add(orbitLine);
      }

      entries.push({
        id: p.id,
        data: p,
        pivot,
        mesh,
        moons: moonsList,
        orbitRadius: p.distance,
        orbitLine
      });
    });

    planetEntriesRef.current = entries;
    setIsLoading(false);

    // 8. Raycasterによるクリック判定
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    const handlePointerDown = (event: MouseEvent | TouchEvent) => {
      const clientX = 'touches' in event ? event.touches[0].clientX : event.clientX;
      const clientY = 'touches' in event ? event.touches[0].clientY : event.clientY;

      const rect = renderer.domElement.getBoundingClientRect();
      mouse.x = ((clientX - rect.left) / rect.width) * 2 - 1;
      mouse.y = -((clientY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(mouse, camera);
      const meshesToTest = planetEntriesRef.current.map((e) => e.mesh);
      const intersects = raycaster.intersectObjects(meshesToTest, false);

      if (intersects.length > 0) {
        const clickedMesh = intersects[0].object as THREE.Mesh;
        const planetId = clickedMesh.userData.id;
        if (planetId) {
          onSelectPlanet?.(planetId);
        }
      }
    };

    const domElement = renderer.domElement;
    domElement.addEventListener('click', handlePointerDown);

    // 9. リサイズ対応
    const handleResize = () => {
      if (!container || !camera || !renderer) return;
      const newWidth = container.clientWidth;
      const newHeight = container.clientHeight;
      camera.aspect = newWidth / newHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(newWidth, newHeight);
    };

    window.addEventListener('resize', handleResize);

    // 10. メインアニメーションループ
    const animate = () => {
      animFrameIdRef.current = requestAnimationFrame(animate);

      const state = simulationStateRef.current;
      const stepSpeed = state.isPaused ? 0 : state.speed;

      // 惑星・月の公転・自転
      planetEntriesRef.current.forEach((entry) => {
        // 公転
        if (entry.data.orbitSpeed > 0 && stepSpeed > 0) {
          entry.pivot.rotation.y += entry.data.orbitSpeed * stepSpeed * 0.15;
        }

        // 自転
        if (stepSpeed > 0) {
          entry.mesh.rotation.y += entry.data.rotationSpeed * stepSpeed * 0.2;
        }

        // 月の公転
        entry.moons.forEach((m) => {
          if (stepSpeed > 0) {
            m.pivot.rotation.y += m.speed * stepSpeed * 0.25;
          }
        });
      });

      // カメラのスムーズフォーカス補間
      if (targetCamPosRef.current && targetLookAtRef.current) {
        camera.position.lerp(targetCamPosRef.current, 0.05);
        controls.target.lerp(targetLookAtRef.current, 0.05);

        // 追従ターゲットに十分近づいたらリセット（操作の自由化）
        if (camera.position.distanceTo(targetCamPosRef.current) < 0.2) {
          targetCamPosRef.current = null;
          targetLookAtRef.current = null;
        }
      }

      controls.update();
      renderer.render(scene, camera);
    };

    animate();

    // クリーンアップ
    return () => {
      if (animFrameIdRef.current) {
        cancelAnimationFrame(animFrameIdRef.current);
      }
      window.removeEventListener('resize', handleResize);
      domElement.removeEventListener('click', handlePointerDown);
      controls.dispose();
      renderer.dispose();
      if (container.contains(domElement)) {
        container.removeChild(domElement);
      }
    };
  }, [planets, onSelectPlanet]);

  return (
    <div className="canvas-container" ref={containerRef}>
      {isLoading && <div className="loading-overlay">3D太陽系空間を構築中...</div>}
    </div>
  );
}

import { Play, Pause, CircleDot, RotateCcw, X } from 'lucide-react';
import { SolarControlsProps } from '../types';

export default function SolarControls({
  planets = [],
  simulationState,
  onSpeedChange,
  onTogglePause,
  onToggleOrbits,
  onSelectPlanet
}: SolarControlsProps) {
  const selectedPlanet = planets.find((p) => p.id === simulationState.selectedPlanetId);

  return (
    <>
      {/* 選択惑星の詳細情報カード（モーダル / サイドパネル） */}
      {selectedPlanet && (
        <section className="info-panel" aria-label="惑星詳細情報">
          <div className="info-header">
            <div>
              <h2 className="info-title">{selectedPlanet.name}</h2>
              <span className="info-subtitle">{selectedPlanet.enName}</span>
            </div>
            <button
              className="info-close-btn"
              onClick={() => onSelectPlanet?.(null)}
              aria-label="詳細パネルを閉じる"
              type="button"
            >
              <X size={16} />
            </button>
          </div>

          <div className="info-body">
            <div className="info-grid">
              <div className="info-stat-box">
                <span className="info-stat-label">赤道直径</span>
                <span className="info-stat-value">{selectedPlanet.diameterKm}</span>
              </div>
              <div className="info-stat-box">
                <span className="info-stat-label">太陽からの平均距離</span>
                <span className="info-stat-value">{selectedPlanet.distanceKm}</span>
              </div>
              <div className="info-stat-box">
                <span className="info-stat-label">公転周期</span>
                <span className="info-stat-value">{selectedPlanet.periodDays}</span>
              </div>
              <div className="info-stat-box">
                <span className="info-stat-label">平均気温</span>
                <span className="info-stat-value">{selectedPlanet.temperature}</span>
              </div>
            </div>

            <p className="info-description">{selectedPlanet.description}</p>
          </div>
        </section>
      )}

      {/* フッター操作パネル群 */}
      <footer className="controls-root">
        {/* 惑星クイック選択バー */}
        <nav className="planet-quick-bar" aria-label="惑星クイック選択">
          <button
            type="button"
            className={
              simulationState.selectedPlanetId === null
                ? 'planet-quick-btn planet-quick-btn-active'
                : 'planet-quick-btn'
            }
            onClick={() => onSelectPlanet?.(null)}
          >
            <RotateCcw size={14} />
            <span>全体俯瞰</span>
          </button>

          {planets.map((planet) => {
            const isActive = simulationState.selectedPlanetId === planet.id;
            return (
              <button
                key={planet.id}
                type="button"
                className={
                  isActive
                    ? 'planet-quick-btn planet-quick-btn-active'
                    : 'planet-quick-btn'
                }
                onClick={() => onSelectPlanet?.(planet.id)}
              >
                <span
                  style={{
                    display: 'inline-block',
                    width: 8,
                    height: 8,
                    borderRadius: '50%',
                    backgroundColor: planet.color
                  }}
                />
                <span>{planet.name}</span>
              </button>
            );
          })}
        </nav>

        {/* シミュレーション操作バー（再生・速度・軌道線） */}
        <div className="control-bar">
          <button
            type="button"
            className={
              simulationState.isPaused
                ? 'btn-control btn-active'
                : 'btn-control'
            }
            onClick={() => onTogglePause?.()}
            aria-label={simulationState.isPaused ? '再開' : '一時停止'}
          >
            {simulationState.isPaused ? (
              <>
                <Play size={16} />
                <span>再生</span>
              </>
            ) : (
              <>
                <Pause size={16} />
                <span>停止</span>
              </>
            )}
          </button>

          <button
            type="button"
            className={
              simulationState.showOrbits
                ? 'btn-control btn-active'
                : 'btn-control'
            }
            onClick={() => onToggleOrbits?.()}
            aria-label="軌道線の表示切替"
          >
            <CircleDot size={16} />
            <span>軌道線</span>
          </button>

          <div className="speed-slider-group">
            <label htmlFor="speed-range" className="slider-label">
              速度: {simulationState.speed.toFixed(1)}x
            </label>
            <input
              id="speed-range"
              type="range"
              className="speed-slider"
              min="0.1"
              max="5.0"
              step="0.1"
              value={simulationState.speed}
              onChange={(e) => onSpeedChange?.(parseFloat(e.target.value))}
            />
          </div>
        </div>
      </footer>
    </>
  );
}

import { useState, useCallback } from 'react';
import planetsData from './data/planets';
import SolarSystemView from './components/SolarSystemView';
import SolarControls from './components/SolarControls';
import { SimulationState } from './types';

export default function App() {
  const [simulationState, setSimulationState] = useState<SimulationState>({
    speed: 1.0,
    isPaused: false,
    showOrbits: true,
    selectedPlanetId: null
  });

  const handleSpeedChange = useCallback((newSpeed: number) => {
    setSimulationState((prev) => ({
      ...prev,
      speed: newSpeed
    }));
  }, []);

  const handleTogglePause = useCallback(() => {
    setSimulationState((prev) => ({
      ...prev,
      isPaused: !prev.isPaused
    }));
  }, []);

  const handleToggleOrbits = useCallback(() => {
    setSimulationState((prev) => ({
      ...prev,
      showOrbits: !prev.showOrbits
    }));
  }, []);

  const handleSelectPlanet = useCallback((id: string | null) => {
    setSimulationState((prev) => ({
      ...prev,
      selectedPlanetId: id
    }));
  }, []);

  return (
    <div className="app-container">
      {/* 3Dキャンバス描画領域 */}
      <SolarSystemView
        planets={planetsData}
        simulationState={simulationState}
        onSelectPlanet={handleSelectPlanet}
      />

      {/* ヘッダー情報バナー */}
      <header className="header-banner">
        <h1 className="header-title">太陽系 3D シミュレーター</h1>
        <p className="header-subtitle">
          リアルタイム公転・自転シミュレーション & 天体百科
        </p>
      </header>

      {/* 操作ヒント案内 */}
      <aside className="legend-hint">
        ドラッグ：視点回転<br />
        スクロール：ズームイン / アウト<br />
        惑星クリック：詳細データ表示
      </aside>

      {/* 操作コントロール & 詳細表示パネル */}
      <SolarControls
        planets={planetsData}
        simulationState={simulationState}
        onSpeedChange={handleSpeedChange}
        onTogglePause={handleTogglePause}
        onToggleOrbits={handleToggleOrbits}
        onSelectPlanet={handleSelectPlanet}
      />
    </div>
  );
}
